with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published)
select id,'النمذجة العددية واستيعاب البيانات الجوية','المعادلات العددية وبنية الشبكات والتهيئة واستيعاب الرصد ومخططات الفيزياء ومعالجة المخرجات والتحقق.',49,false from c
on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'البنية العددية واستيعاب البيانات',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الفيزياء والمعالجة والتحقق',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit_title) as (values
('numerical-weather-prediction-fundamentals','أسس التنبؤ العددي بالطقس','من المعادلات الحاكمة إلى إنتاج التنبؤ','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يعتمد التنبؤ العددي على حل تقريبي لمعادلات حفظ الكتلة والزخم والطاقة وبخار الماء على شبكة مكانية وزمنية. تبدأ الدورة بتهيئة الحالة الجوية، ثم تطبيق الفيزياء والمعادلات العددية، وإنتاج حقول متوقعة قابلة للتحقق."},{"type":"heading","text":"الأساس الرياضي والحاسوبي"},{"type":"text","text":"يرتبط أسس التنبؤ العددي بالطقس ببنية النموذج وتمثيل المتغيرات على الشبكة وبالافتراضات العددية والفيزيائية. ينبغي توثيق الوحدات والإحداثيات والمرجع الزمني ومجال صلاحية كل تقريب قبل تفسير المخرجات."},{"type":"heading","text":"خطوات العمل"},{"type":"list","items":["تحديد المتغيرات والمدخلات والمخرجات ومجالاتها ووحداتها.","فحص جودة الرصد والتحليل الابتدائي والشروط الحدية.","اختيار الإعدادات العددية والفيزيائية المناسبة للمقياس.","تنفيذ اختبار حساسية لتغيير الإعدادات المؤثرة.","مقارنة المخرجات برصد مستقل وتحليل الأخطاء مكانياً وزمنياً."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تجربة تحقق","text":"أنشئ تجربتين تختلفان في إعداد واحد مرتبط بموضوع أسس التنبؤ العددي بالطقس مع تثبيت بقية الشروط. قارن الحقول الناتجة ومقاييس الخطأ، ثم حدد إن كان الفرق ذا دلالة تشغيلية أم يقع ضمن التباين المتوقع."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ارسم مخطط دورة التنبؤ العددي من الرصد إلى التهيئة ثم التكامل الزمني وإنتاج الخرائط والتحقق."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["أخطاء الرصد والتحليل الابتدائي.","عدم كفاية الدقة المكانية أو الزمنية.","تبسيط العمليات الفيزيائية دون الشبكية.","عدم اتساق الوحدات أو أزمنة الصلاحية.","اختيار عينة تحقق غير ممثلة أو غير مستقلة."]},{"type":"callout","text":"مبدأ مهني: لا تقارن نموذجين قبل توحيد الفترة المرجعية والمتغير والوحدة وطريقة المطابقة المكانية والزمنية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم أسس التنبؤ العددي بالطقس إطاراً لفهم كيفية بناء التنبؤ العددي وتقييمه، ويؤكد أن جودة الناتج تعتمد على تكامل الفيزياء والرياضيات والبيانات والتحقق المستقل."}]}'::jsonb,5960,60,'["شرح المفاهيم الأساسية في أسس التنبؤ العددي بالطقس","تحديد المدخلات والافتراضات العددية والفيزيائية","تصميم اختبار تحقق وتحليل عدم اليقين"]'::jsonb,'البنية العددية واستيعاب البيانات'),
('primitive-equations-atmosphere','المعادلات الأساسية لحركة الغلاف الجوي','حفظ الكتلة والزخم والطاقة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تصف المعادلات البدائية تطور الرياح والحرارة والضغط والرطوبة، مع افتراضات تقريبية تتعلق بالهيدروستاتيكية أو عدمها. ترتبط دقة الحل بتمثيل القوى والتدفقات والشروط الحدية."},{"type":"heading","text":"الأساس الرياضي والحاسوبي"},{"type":"text","text":"يرتبط المعادلات الأساسية لحركة الغلاف الجوي ببنية النموذج وتمثيل المتغيرات على الشبكة وبالافتراضات العددية والفيزيائية. ينبغي توثيق الوحدات والإحداثيات والمرجع الزمني ومجال صلاحية كل تقريب قبل تفسير المخرجات."},{"type":"heading","text":"خطوات العمل"},{"type":"list","items":["تحديد المتغيرات والمدخلات والمخرجات ومجالاتها ووحداتها.","فحص جودة الرصد والتحليل الابتدائي والشروط الحدية.","اختيار الإعدادات العددية والفيزيائية المناسبة للمقياس.","تنفيذ اختبار حساسية لتغيير الإعدادات المؤثرة.","مقارنة المخرجات برصد مستقل وتحليل الأخطاء مكانياً وزمنياً."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تجربة تحقق","text":"أنشئ تجربتين تختلفان في إعداد واحد مرتبط بموضوع المعادلات الأساسية لحركة الغلاف الجوي مع تثبيت بقية الشروط. قارن الحقول الناتجة ومقاييس الخطأ، ثم حدد إن كان الفرق ذا دلالة تشغيلية أم يقع ضمن التباين المتوقع."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد معنى كل حد في معادلة الزخم الأفقية، ووضح الفرق بين التسارع الناتج عن تدرج الضغط وتأثير كوريوليس."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["أخطاء الرصد والتحليل الابتدائي.","عدم كفاية الدقة المكانية أو الزمنية.","تبسيط العمليات الفيزيائية دون الشبكية.","عدم اتساق الوحدات أو أزمنة الصلاحية.","اختيار عينة تحقق غير ممثلة أو غير مستقلة."]},{"type":"callout","text":"مبدأ مهني: لا تقارن نموذجين قبل توحيد الفترة المرجعية والمتغير والوحدة وطريقة المطابقة المكانية والزمنية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم المعادلات الأساسية لحركة الغلاف الجوي إطاراً لفهم كيفية بناء التنبؤ العددي وتقييمه، ويؤكد أن جودة الناتج تعتمد على تكامل الفيزياء والرياضيات والبيانات والتحقق المستقل."}]}'::jsonb,5970,60,'["شرح المفاهيم الأساسية في المعادلات الأساسية لحركة الغلاف الجوي","تحديد المدخلات والافتراضات العددية والفيزيائية","تصميم اختبار تحقق وتحليل عدم اليقين"]'::jsonb,'البنية العددية واستيعاب البيانات'),
('hydrostatic-and-nonhydrostatic-models','النماذج الهيدروستاتيكية وغير الهيدروستاتيكية','اختيار الصياغة وفق المقياس المكاني','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تفترض النماذج الهيدروستاتيكية توازناً تقريبياً رأسياً بين تدرج الضغط والوزن، بينما تحل النماذج غير الهيدروستاتيكية تسارع الحركة الرأسية صراحة. يهم الاختيار عند تمثيل الحمل العميق والظواهر ذات المقاييس الصغيرة."},{"type":"heading","text":"الأساس الرياضي والحاسوبي"},{"type":"text","text":"يرتبط النماذج الهيدروستاتيكية وغير الهيدروستاتيكية ببنية النموذج وتمثيل المتغيرات على الشبكة وبالافتراضات العددية والفيزيائية. ينبغي توثيق الوحدات والإحداثيات والمرجع الزمني ومجال صلاحية كل تقريب قبل تفسير المخرجات."},{"type":"heading","text":"خطوات العمل"},{"type":"list","items":["تحديد المتغيرات والمدخلات والمخرجات ومجالاتها ووحداتها.","فحص جودة الرصد والتحليل الابتدائي والشروط الحدية.","اختيار الإعدادات العددية والفيزيائية المناسبة للمقياس.","تنفيذ اختبار حساسية لتغيير الإعدادات المؤثرة.","مقارنة المخرجات برصد مستقل وتحليل الأخطاء مكانياً وزمنياً."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تجربة تحقق","text":"أنشئ تجربتين تختلفان في إعداد واحد مرتبط بموضوع النماذج الهيدروستاتيكية وغير الهيدروستاتيكية مع تثبيت بقية الشروط. قارن الحقول الناتجة ومقاييس الخطأ، ثم حدد إن كان الفرق ذا دلالة تشغيلية أم يقع ضمن التباين المتوقع."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن متطلبات تمثيل عاصفة رعدية محلية مع نظام جوي واسع النطاق، وعلل اختيار الصياغة."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["أخطاء الرصد والتحليل الابتدائي.","عدم كفاية الدقة المكانية أو الزمنية.","تبسيط العمليات الفيزيائية دون الشبكية.","عدم اتساق الوحدات أو أزمنة الصلاحية.","اختيار عينة تحقق غير ممثلة أو غير مستقلة."]},{"type":"callout","text":"مبدأ مهني: لا تقارن نموذجين قبل توحيد الفترة المرجعية والمتغير والوحدة وطريقة المطابقة المكانية والزمنية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم النماذج الهيدروستاتيكية وغير الهيدروستاتيكية إطاراً لفهم كيفية بناء التنبؤ العددي وتقييمه، ويؤكد أن جودة الناتج تعتمد على تكامل الفيزياء والرياضيات والبيانات والتحقق المستقل."}]}'::jsonb,5980,60,'["شرح المفاهيم الأساسية في النماذج الهيدروستاتيكية وغير الهيدروستاتيكية","تحديد المدخلات والافتراضات العددية والفيزيائية","تصميم اختبار تحقق وتحليل عدم اليقين"]'::jsonb,'البنية العددية واستيعاب البيانات'),
('model-grid-resolution','دقة الشبكة في النماذج العددية','التمثيل المكاني والزمني والظواهر دون الشبكية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تحدد دقة الشبكة أصغر البنى التي يمكن تمثيلها مباشرة، لكن زيادة الدقة ترفع الكلفة الحسابية ولا تلغي أخطاء الفيزياء أو الرصد. كما ترتبط الخطوة الزمنية باستقرار المخطط العددي وسرعة الموجات."},{"type":"heading","text":"الأساس الرياضي والحاسوبي"},{"type":"text","text":"يرتبط دقة الشبكة في النماذج العددية ببنية النموذج وتمثيل المتغيرات على الشبكة وبالافتراضات العددية والفيزيائية. ينبغي توثيق الوحدات والإحداثيات والمرجع الزمني ومجال صلاحية كل تقريب قبل تفسير المخرجات."},{"type":"heading","text":"خطوات العمل"},{"type":"list","items":["تحديد المتغيرات والمدخلات والمخرجات ومجالاتها ووحداتها.","فحص جودة الرصد والتحليل الابتدائي والشروط الحدية.","اختيار الإعدادات العددية والفيزيائية المناسبة للمقياس.","تنفيذ اختبار حساسية لتغيير الإعدادات المؤثرة.","مقارنة المخرجات برصد مستقل وتحليل الأخطاء مكانياً وزمنياً."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تجربة تحقق","text":"أنشئ تجربتين تختلفان في إعداد واحد مرتبط بموضوع دقة الشبكة في النماذج العددية مع تثبيت بقية الشروط. قارن الحقول الناتجة ومقاييس الخطأ، ثم حدد إن كان الفرق ذا دلالة تشغيلية أم يقع ضمن التباين المتوقع."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح لماذا لا يعني تصغير الشبكة تلقائياً تحسناً متناسباً في دقة التنبؤ."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["أخطاء الرصد والتحليل الابتدائي.","عدم كفاية الدقة المكانية أو الزمنية.","تبسيط العمليات الفيزيائية دون الشبكية.","عدم اتساق الوحدات أو أزمنة الصلاحية.","اختيار عينة تحقق غير ممثلة أو غير مستقلة."]},{"type":"callout","text":"مبدأ مهني: لا تقارن نموذجين قبل توحيد الفترة المرجعية والمتغير والوحدة وطريقة المطابقة المكانية والزمنية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم دقة الشبكة في النماذج العددية إطاراً لفهم كيفية بناء التنبؤ العددي وتقييمه، ويؤكد أن جودة الناتج تعتمد على تكامل الفيزياء والرياضيات والبيانات والتحقق المستقل."}]}'::jsonb,5990,60,'["شرح المفاهيم الأساسية في دقة الشبكة في النماذج العددية","تحديد المدخلات والافتراضات العددية والفيزيائية","تصميم اختبار تحقق وتحليل عدم اليقين"]'::jsonb,'البنية العددية واستيعاب البيانات'),
('numerical-stability-cfl','الاستقرار العددي وشرط كوران','العلاقة بين الخطوة الزمنية وحجم الشبكة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يربط شرط كوران الخطوة الزمنية بسرعة انتقال المعلومات وحجم الخلية، ويساعد على تجنب عدم الاستقرار في بعض المخططات الصريحة. تختلف الحدود الدقيقة باختلاف المعادلات والمخطط المستخدم."},{"type":"heading","text":"الأساس الرياضي والحاسوبي"},{"type":"text","text":"يرتبط الاستقرار العددي وشرط كوران ببنية النموذج وتمثيل المتغيرات على الشبكة وبالافتراضات العددية والفيزيائية. ينبغي توثيق الوحدات والإحداثيات والمرجع الزمني ومجال صلاحية كل تقريب قبل تفسير المخرجات."},{"type":"heading","text":"خطوات العمل"},{"type":"list","items":["تحديد المتغيرات والمدخلات والمخرجات ومجالاتها ووحداتها.","فحص جودة الرصد والتحليل الابتدائي والشروط الحدية.","اختيار الإعدادات العددية والفيزيائية المناسبة للمقياس.","تنفيذ اختبار حساسية لتغيير الإعدادات المؤثرة.","مقارنة المخرجات برصد مستقل وتحليل الأخطاء مكانياً وزمنياً."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تجربة تحقق","text":"أنشئ تجربتين تختلفان في إعداد واحد مرتبط بموضوع الاستقرار العددي وشرط كوران مع تثبيت بقية الشروط. قارن الحقول الناتجة ومقاييس الخطأ، ثم حدد إن كان الفرق ذا دلالة تشغيلية أم يقع ضمن التباين المتوقع."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"إذا خُفض طول الشبكة إلى النصف، ناقش أثر ذلك المحتمل في الخطوة الزمنية والكلفة الحسابية."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["أخطاء الرصد والتحليل الابتدائي.","عدم كفاية الدقة المكانية أو الزمنية.","تبسيط العمليات الفيزيائية دون الشبكية.","عدم اتساق الوحدات أو أزمنة الصلاحية.","اختيار عينة تحقق غير ممثلة أو غير مستقلة."]},{"type":"callout","text":"مبدأ مهني: لا تقارن نموذجين قبل توحيد الفترة المرجعية والمتغير والوحدة وطريقة المطابقة المكانية والزمنية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم الاستقرار العددي وشرط كوران إطاراً لفهم كيفية بناء التنبؤ العددي وتقييمه، ويؤكد أن جودة الناتج تعتمد على تكامل الفيزياء والرياضيات والبيانات والتحقق المستقل."}]}'::jsonb,6000,60,'["شرح المفاهيم الأساسية في الاستقرار العددي وشرط كوران","تحديد المدخلات والافتراضات العددية والفيزيائية","تصميم اختبار تحقق وتحليل عدم اليقين"]'::jsonb,'البنية العددية واستيعاب البيانات'),
('finite-difference-finite-volume','الفروق المحددة والحجوم المحددة','مقارنة طرق التقريب والحفظ العددي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تقرب الفروق المحددة المشتقات عند نقاط الشبكة، بينما تركز الحجوم المحددة على موازنة التدفقات عبر حدود الخلايا. تكون المحافظة على الكميات مهمة في نمذجة النقل والرطوبة والطاقة."},{"type":"heading","text":"الأساس الرياضي والحاسوبي"},{"type":"text","text":"يرتبط الفروق المحددة والحجوم المحددة ببنية النموذج وتمثيل المتغيرات على الشبكة وبالافتراضات العددية والفيزيائية. ينبغي توثيق الوحدات والإحداثيات والمرجع الزمني ومجال صلاحية كل تقريب قبل تفسير المخرجات."},{"type":"heading","text":"خطوات العمل"},{"type":"list","items":["تحديد المتغيرات والمدخلات والمخرجات ومجالاتها ووحداتها.","فحص جودة الرصد والتحليل الابتدائي والشروط الحدية.","اختيار الإعدادات العددية والفيزيائية المناسبة للمقياس.","تنفيذ اختبار حساسية لتغيير الإعدادات المؤثرة.","مقارنة المخرجات برصد مستقل وتحليل الأخطاء مكانياً وزمنياً."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تجربة تحقق","text":"أنشئ تجربتين تختلفان في إعداد واحد مرتبط بموضوع الفروق المحددة والحجوم المحددة مع تثبيت بقية الشروط. قارن الحقول الناتجة ومقاييس الخطأ، ثم حدد إن كان الفرق ذا دلالة تشغيلية أم يقع ضمن التباين المتوقع."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن الطريقتين عند تمثيل نقل كمية محفوظة عبر خلية، وحدد ما الذي ينبغي اختباره."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["أخطاء الرصد والتحليل الابتدائي.","عدم كفاية الدقة المكانية أو الزمنية.","تبسيط العمليات الفيزيائية دون الشبكية.","عدم اتساق الوحدات أو أزمنة الصلاحية.","اختيار عينة تحقق غير ممثلة أو غير مستقلة."]},{"type":"callout","text":"مبدأ مهني: لا تقارن نموذجين قبل توحيد الفترة المرجعية والمتغير والوحدة وطريقة المطابقة المكانية والزمنية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم الفروق المحددة والحجوم المحددة إطاراً لفهم كيفية بناء التنبؤ العددي وتقييمه، ويؤكد أن جودة الناتج تعتمد على تكامل الفيزياء والرياضيات والبيانات والتحقق المستقل."}]}'::jsonb,6010,60,'["شرح المفاهيم الأساسية في الفروق المحددة والحجوم المحددة","تحديد المدخلات والافتراضات العددية والفيزيائية","تصميم اختبار تحقق وتحليل عدم اليقين"]'::jsonb,'البنية العددية واستيعاب البيانات'),
('model-initialization-analysis','تهيئة النماذج والتحليل الابتدائي','دمج الرصد في حالة ابتدائية متسقة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تهدف التهيئة إلى إنتاج حالة ابتدائية قريبة من الواقع ومتوازنة ديناميكياً. قد تتسبب أخطاء الرصد أو التمثيل أو عدم الاتساق في انحرافات مبكرة، لذلك تراجع جودة التحليل والحقول المشتقة."},{"type":"heading","text":"الأساس الرياضي والحاسوبي"},{"type":"text","text":"يرتبط تهيئة النماذج والتحليل الابتدائي ببنية النموذج وتمثيل المتغيرات على الشبكة وبالافتراضات العددية والفيزيائية. ينبغي توثيق الوحدات والإحداثيات والمرجع الزمني ومجال صلاحية كل تقريب قبل تفسير المخرجات."},{"type":"heading","text":"خطوات العمل"},{"type":"list","items":["تحديد المتغيرات والمدخلات والمخرجات ومجالاتها ووحداتها.","فحص جودة الرصد والتحليل الابتدائي والشروط الحدية.","اختيار الإعدادات العددية والفيزيائية المناسبة للمقياس.","تنفيذ اختبار حساسية لتغيير الإعدادات المؤثرة.","مقارنة المخرجات برصد مستقل وتحليل الأخطاء مكانياً وزمنياً."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تجربة تحقق","text":"أنشئ تجربتين تختلفان في إعداد واحد مرتبط بموضوع تهيئة النماذج والتحليل الابتدائي مع تثبيت بقية الشروط. قارن الحقول الناتجة ومقاييس الخطأ، ثم حدد إن كان الفرق ذا دلالة تشغيلية أم يقع ضمن التباين المتوقع."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد ثلاثة اختبارات جودة يجب تنفيذها قبل بدء تشغيل نموذج عددي."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["أخطاء الرصد والتحليل الابتدائي.","عدم كفاية الدقة المكانية أو الزمنية.","تبسيط العمليات الفيزيائية دون الشبكية.","عدم اتساق الوحدات أو أزمنة الصلاحية.","اختيار عينة تحقق غير ممثلة أو غير مستقلة."]},{"type":"callout","text":"مبدأ مهني: لا تقارن نموذجين قبل توحيد الفترة المرجعية والمتغير والوحدة وطريقة المطابقة المكانية والزمنية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم تهيئة النماذج والتحليل الابتدائي إطاراً لفهم كيفية بناء التنبؤ العددي وتقييمه، ويؤكد أن جودة الناتج تعتمد على تكامل الفيزياء والرياضيات والبيانات والتحقق المستقل."}]}'::jsonb,6020,60,'["شرح المفاهيم الأساسية في تهيئة النماذج والتحليل الابتدائي","تحديد المدخلات والافتراضات العددية والفيزيائية","تصميم اختبار تحقق وتحليل عدم اليقين"]'::jsonb,'البنية العددية واستيعاب البيانات'),
('data-assimilation-3dvar-4dvar','استيعاب البيانات بتقنيتي 3D-Var و4D-Var','القيود الإحصائية والزمنية في التحليل','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تستخدم 3D-Var دالة كلفة لدمج الرصد والخلفية عند وقت تحليل، بينما تستفيد 4D-Var من تطور النموذج خلال نافذة زمنية لربط الرصد بمسار الحالة. تتوقف الجودة على توصيف أخطاء الخلفية والرصد."},{"type":"heading","text":"الأساس الرياضي والحاسوبي"},{"type":"text","text":"يرتبط استيعاب البيانات بتقنيتي 3D-Var و4D-Var ببنية النموذج وتمثيل المتغيرات على الشبكة وبالافتراضات العددية والفيزيائية. ينبغي توثيق الوحدات والإحداثيات والمرجع الزمني ومجال صلاحية كل تقريب قبل تفسير المخرجات."},{"type":"heading","text":"خطوات العمل"},{"type":"list","items":["تحديد المتغيرات والمدخلات والمخرجات ومجالاتها ووحداتها.","فحص جودة الرصد والتحليل الابتدائي والشروط الحدية.","اختيار الإعدادات العددية والفيزيائية المناسبة للمقياس.","تنفيذ اختبار حساسية لتغيير الإعدادات المؤثرة.","مقارنة المخرجات برصد مستقل وتحليل الأخطاء مكانياً وزمنياً."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تجربة تحقق","text":"أنشئ تجربتين تختلفان في إعداد واحد مرتبط بموضوع استيعاب البيانات بتقنيتي 3D-Var و4D-Var مع تثبيت بقية الشروط. قارن الحقول الناتجة ومقاييس الخطأ، ثم حدد إن كان الفرق ذا دلالة تشغيلية أم يقع ضمن التباين المتوقع."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح دور مصفوفات الخطأ في دالة الكلفة، ولماذا يؤثر توصيفها في وزن الرصد."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["أخطاء الرصد والتحليل الابتدائي.","عدم كفاية الدقة المكانية أو الزمنية.","تبسيط العمليات الفيزيائية دون الشبكية.","عدم اتساق الوحدات أو أزمنة الصلاحية.","اختيار عينة تحقق غير ممثلة أو غير مستقلة."]},{"type":"callout","text":"مبدأ مهني: لا تقارن نموذجين قبل توحيد الفترة المرجعية والمتغير والوحدة وطريقة المطابقة المكانية والزمنية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم استيعاب البيانات بتقنيتي 3D-Var و4D-Var إطاراً لفهم كيفية بناء التنبؤ العددي وتقييمه، ويؤكد أن جودة الناتج تعتمد على تكامل الفيزياء والرياضيات والبيانات والتحقق المستقل."}]}'::jsonb,6030,60,'["شرح المفاهيم الأساسية في استيعاب البيانات بتقنيتي 3D-Var و4D-Var","تحديد المدخلات والافتراضات العددية والفيزيائية","تصميم اختبار تحقق وتحليل عدم اليقين"]'::jsonb,'البنية العددية واستيعاب البيانات'),
('ensemble-kalman-filter','مرشح كالمان التجميعي','تقدير الحالة وعدم اليقين من مجموعة محاكاة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يستخدم مرشح كالمان التجميعي مجموعة حالات لتقريب إحصاءات الخطأ وتحديث التنبؤ بالرصد. يتأثر الأداء بحجم المجموعة والتمثيل المكاني للترابط وبالحاجة إلى تقنيات مثل التضخيم والتوطين."},{"type":"heading","text":"الأساس الرياضي والحاسوبي"},{"type":"text","text":"يرتبط مرشح كالمان التجميعي ببنية النموذج وتمثيل المتغيرات على الشبكة وبالافتراضات العددية والفيزيائية. ينبغي توثيق الوحدات والإحداثيات والمرجع الزمني ومجال صلاحية كل تقريب قبل تفسير المخرجات."},{"type":"heading","text":"خطوات العمل"},{"type":"list","items":["تحديد المتغيرات والمدخلات والمخرجات ومجالاتها ووحداتها.","فحص جودة الرصد والتحليل الابتدائي والشروط الحدية.","اختيار الإعدادات العددية والفيزيائية المناسبة للمقياس.","تنفيذ اختبار حساسية لتغيير الإعدادات المؤثرة.","مقارنة المخرجات برصد مستقل وتحليل الأخطاء مكانياً وزمنياً."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تجربة تحقق","text":"أنشئ تجربتين تختلفان في إعداد واحد مرتبط بموضوع مرشح كالمان التجميعي مع تثبيت بقية الشروط. قارن الحقول الناتجة ومقاييس الخطأ، ثم حدد إن كان الفرق ذا دلالة تشغيلية أم يقع ضمن التباين المتوقع."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"وضح كيف تساعد مجموعة تنبؤات على تقدير عدم يقين الحالة مقارنة بتنبؤ منفرد."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["أخطاء الرصد والتحليل الابتدائي.","عدم كفاية الدقة المكانية أو الزمنية.","تبسيط العمليات الفيزيائية دون الشبكية.","عدم اتساق الوحدات أو أزمنة الصلاحية.","اختيار عينة تحقق غير ممثلة أو غير مستقلة."]},{"type":"callout","text":"مبدأ مهني: لا تقارن نموذجين قبل توحيد الفترة المرجعية والمتغير والوحدة وطريقة المطابقة المكانية والزمنية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم مرشح كالمان التجميعي إطاراً لفهم كيفية بناء التنبؤ العددي وتقييمه، ويؤكد أن جودة الناتج تعتمد على تكامل الفيزياء والرياضيات والبيانات والتحقق المستقل."}]}