('background-error-covariance','ترابط أخطاء الخلفية','الأطوال المكانية والعلاقات بين المتغيرات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تصف مصفوفة ترابط أخطاء الخلفية مقدار تغاير أخطاء الحالة بين المواقع والمتغيرات. يحدد طول الترابط مدى انتشار تأثير الرصد، وقد يؤدي الاختيار غير المناسب إلى نشر معلومات زائدة أو إضعافها."},{"type":"heading","text":"الأساس الرياضي والحاسوبي"},{"type":"text","text":"يرتبط ترابط أخطاء الخلفية ببنية النموذج وتمثيل المتغيرات على الشبكة وبالافتراضات العددية والفيزيائية. ينبغي توثيق الوحدات والإحداثيات والمرجع الزمني ومجال صلاحية كل تقريب قبل تفسير المخرجات."},{"type":"heading","text":"خطوات العمل"},{"type":"list","items":["تحديد المتغيرات والمدخلات والمخرجات ومجالاتها ووحداتها.","فحص جودة الرصد والتحليل الابتدائي والشروط الحدية.","اختيار الإعدادات العددية والفيزيائية المناسبة للمقياس.","تنفيذ اختبار حساسية لتغيير الإعدادات المؤثرة.","مقارنة المخرجات برصد مستقل وتحليل الأخطاء مكانياً وزمنياً."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تجربة تحقق","text":"أنشئ تجربتين تختلفان في إعداد واحد مرتبط بموضوع ترابط أخطاء الخلفية مع تثبيت بقية الشروط. قارن الحقول الناتجة ومقاييس الخطأ، ثم حدد إن كان الفرق ذا دلالة تشغيلية أم يقع ضمن التباين المتوقع."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ناقش أثر طول ترابط مكاني مبالغ فيه عند استيعاب قياس محطة محلية."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["أخطاء الرصد والتحليل الابتدائي.","عدم كفاية الدقة المكانية أو الزمنية.","تبسيط العمليات الفيزيائية دون الشبكية.","عدم اتساق الوحدات أو أزمنة الصلاحية.","اختيار عينة تحقق غير ممثلة أو غير مستقلة."]},{"type":"callout","text":"مبدأ مهني: لا تقارن نموذجين قبل توحيد الفترة المرجعية والمتغير والوحدة وطريقة المطابقة المكانية والزمنية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم ترابط أخطاء الخلفية إطاراً لفهم كيفية بناء التنبؤ العددي وتقييمه، ويؤكد أن جودة الناتج تعتمد على تكامل الفيزياء والرياضيات والبيانات والتحقق المستقل."}]}'::jsonb,6050,60,'["شرح المفاهيم الأساسية في ترابط أخطاء الخلفية","تحديد المدخلات والافتراضات العددية والفيزيائية","تصميم اختبار تحقق وتحليل عدم اليقين"]'::jsonb,'البنية العددية واستيعاب البيانات'),
('observation-operator-quality-control','مؤثر الرصد وضبط جودة البيانات','تحويل حالة النموذج إلى كمية قابلة للمقارنة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يحول مؤثر الرصد متغيرات النموذج إلى الكمية التي يقيسها الجهاز، وقد يتضمن تمثيل الاستجابة الطيفية أو المتوسط المكاني أو الارتفاع. تسبق الاستيعاب اختبارات الاتساق والشذوذ والتمثيل."},{"type":"heading","text":"الأساس الرياضي والحاسوبي"},{"type":"text","text":"يرتبط مؤثر الرصد وضبط جودة البيانات ببنية النموذج وتمثيل المتغيرات على الشبكة وبالافتراضات العددية والفيزيائية. ينبغي توثيق الوحدات والإحداثيات والمرجع الزمني ومجال صلاحية كل تقريب قبل تفسير المخرجات."},{"type":"heading","text":"خطوات العمل"},{"type":"list","items":["تحديد المتغيرات والمدخلات والمخرجات ومجالاتها ووحداتها.","فحص جودة الرصد والتحليل الابتدائي والشروط الحدية.","اختيار الإعدادات العددية والفيزيائية المناسبة للمقياس.","تنفيذ اختبار حساسية لتغيير الإعدادات المؤثرة.","مقارنة المخرجات برصد مستقل وتحليل الأخطاء مكانياً وزمنياً."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تجربة تحقق","text":"أنشئ تجربتين تختلفان في إعداد واحد مرتبط بموضوع مؤثر الرصد وضبط جودة البيانات مع تثبيت بقية الشروط. قارن الحقول الناتجة ومقاييس الخطأ، ثم حدد إن كان الفرق ذا دلالة تشغيلية أم يقع ضمن التباين المتوقع."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"أعط مثالاً يوضح لماذا لا تقارن قراءة محطة سطحية مباشرة بمتغير نموذجي عند ارتفاع مختلف."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["أخطاء الرصد والتحليل الابتدائي.","عدم كفاية الدقة المكانية أو الزمنية.","تبسيط العمليات الفيزيائية دون الشبكية.","عدم اتساق الوحدات أو أزمنة الصلاحية.","اختيار عينة تحقق غير ممثلة أو غير مستقلة."]},{"type":"callout","text":"مبدأ مهني: لا تقارن نموذجين قبل توحيد الفترة المرجعية والمتغير والوحدة وطريقة المطابقة المكانية والزمنية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم مؤثر الرصد وضبط جودة البيانات إطاراً لفهم كيفية بناء التنبؤ العددي وتقييمه، ويؤكد أن جودة الناتج تعتمد على تكامل الفيزياء والرياضيات والبيانات والتحقق المستقل."}]}'::jsonb,6060,60,'["شرح المفاهيم الأساسية في مؤثر الرصد وضبط جودة البيانات","تحديد المدخلات والافتراضات العددية والفيزيائية","تصميم اختبار تحقق وتحليل عدم اليقين"]'::jsonb,'الفيزياء والمعالجة والتحقق'),
('model-physics-parameterization','المعاملات الفيزيائية دون الشبكية','السحب والاضطراب والإشعاع والسطح','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تمثل المعاملات الفيزيائية عمليات أصغر من الشبكة أو معقدة التمثيل المباشر، مثل السحب والاضطراب والإشعاع والتبادل السطحي. تضاف هذه العمليات عبر صيغ تقريبية تحتاج إلى تقييم مستمر."},{"type":"heading","text":"الأساس الرياضي والحاسوبي"},{"type":"text","text":"يرتبط المعاملات الفيزيائية دون الشبكية ببنية النموذج وتمثيل المتغيرات على الشبكة وبالافتراضات العددية والفيزيائية. ينبغي توثيق الوحدات والإحداثيات والمرجع الزمني ومجال صلاحية كل تقريب قبل تفسير المخرجات."},{"type":"heading","text":"خطوات العمل"},{"type":"list","items":["تحديد المتغيرات والمدخلات والمخرجات ومجالاتها ووحداتها.","فحص جودة الرصد والتحليل الابتدائي والشروط الحدية.","اختيار الإعدادات العددية والفيزيائية المناسبة للمقياس.","تنفيذ اختبار حساسية لتغيير الإعدادات المؤثرة.","مقارنة المخرجات برصد مستقل وتحليل الأخطاء مكانياً وزمنياً."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تجربة تحقق","text":"أنشئ تجربتين تختلفان في إعداد واحد مرتبط بموضوع المعاملات الفيزيائية دون الشبكية مع تثبيت بقية الشروط. قارن الحقول الناتجة ومقاييس الخطأ، ثم حدد إن كان الفرق ذا دلالة تشغيلية أم يقع ضمن التباين المتوقع."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد عملية جوية واحدة يصعب حلها مباشرة على شبكة متوسطة الدقة، واشرح كيف تمثل تقريبياً."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["أخطاء الرصد والتحليل الابتدائي.","عدم كفاية الدقة المكانية أو الزمنية.","تبسيط العمليات الفيزيائية دون الشبكية.","عدم اتساق الوحدات أو أزمنة الصلاحية.","اختيار عينة تحقق غير ممثلة أو غير مستقلة."]},{"type":"callout","text":"مبدأ مهني: لا تقارن نموذجين قبل توحيد الفترة المرجعية والمتغير والوحدة وطريقة المطابقة المكانية والزمنية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم المعاملات الفيزيائية دون الشبكية إطاراً لفهم كيفية بناء التنبؤ العددي وتقييمه، ويؤكد أن جودة الناتج تعتمد على تكامل الفيزياء والرياضيات والبيانات والتحقق المستقل."}]}'::jsonb,6070,60,'["شرح المفاهيم الأساسية في المعاملات الفيزيائية دون الشبكية","تحديد المدخلات والافتراضات العددية والفيزيائية","تصميم اختبار تحقق وتحليل عدم اليقين"]'::jsonb,'الفيزياء والمعالجة والتحقق'),
