('model-output-postprocessing','معالجة مخرجات النماذج العددية','التصحيح والتحويل والاستخراج المكاني','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تشمل المعالجة اللاحقة استخراج المتغيرات وتحويل الوحدات وإعادة الشبك والتصحيح الإحصائي وإنتاج مؤشرات قابلة للاستخدام. يجب الاحتفاظ بالبيانات الخام وتوثيق كل خطوة لتجنب تغيير معنى المتغير."},{"type":"heading","text":"الأساس الرياضي والحاسوبي"},{"type":"text","text":"يرتبط معالجة مخرجات النماذج العددية ببنية النموذج وتمثيل المتغيرات على الشبكة وبالافتراضات العددية والفيزيائية. ينبغي توثيق الوحدات والإحداثيات والمرجع الزمني ومجال صلاحية كل تقريب قبل تفسير المخرجات."},{"type":"heading","text":"خطوات العمل"},{"type":"list","items":["تحديد المتغيرات والمدخلات والمخرجات ومجالاتها ووحداتها.","فحص جودة الرصد والتحليل الابتدائي والشروط الحدية.","اختيار الإعدادات العددية والفيزيائية المناسبة للمقياس.","تنفيذ اختبار حساسية لتغيير الإعدادات المؤثرة.","مقارنة المخرجات برصد مستقل وتحليل الأخطاء مكانياً وزمنياً."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تجربة تحقق","text":"أنشئ تجربتين تختلفان في إعداد واحد مرتبط بموضوع معالجة مخرجات النماذج العددية مع تثبيت بقية الشروط. قارن الحقول الناتجة ومقاييس الخطأ، ثم حدد إن كان الفرق ذا دلالة تشغيلية أم يقع ضمن التباين المتوقع."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ضع سلسلة معالجة لمخرجات هطول كل ثلاث ساعات حتى إنتاج تراكم يومي مع اختبار الوحدات."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["أخطاء الرصد والتحليل الابتدائي.","عدم كفاية الدقة المكانية أو الزمنية.","تبسيط العمليات الفيزيائية دون الشبكية.","عدم اتساق الوحدات أو أزمنة الصلاحية.","اختيار عينة تحقق غير ممثلة أو غير مستقلة."]},{"type":"callout","text":"مبدأ مهني: لا تقارن نموذجين قبل توحيد الفترة المرجعية والمتغير والوحدة وطريقة المطابقة المكانية والزمنية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم معالجة مخرجات النماذج العددية إطاراً لفهم كيفية بناء التنبؤ العددي وتقييمه، ويؤكد أن جودة الناتج تعتمد على تكامل الفيزياء والرياضيات والبيانات والتحقق المستقل."}]}'::jsonb,6140,60,'["شرح المفاهيم الأساسية في معالجة مخرجات النماذج العددية","تحديد المدخلات والافتراضات العددية والفيزيائية","تصميم اختبار تحقق وتحليل عدم اليقين"]'::jsonb,'الفيزياء والمعالجة والتحقق'),
('numerical-weather-prediction-verification','التحقق من التنبؤ العددي','الانحياز والخطأ والمهارة والاعتمادية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يستخدم التحقق مقارنة التنبؤ بالرصد المرجعي وفق أزمنة ومواقع وتعريفات متوافقة. تشمل المقاييس MAE وRMSE والانحياز ومهارة التنبؤ، ويجب تفسيرها بحسب المتغير والتوزيع المكاني والزمني."},{"type":"heading","text":"الأساس الرياضي والحاسوبي"},{"type":"text","text":"يرتبط التحقق من التنبؤ العددي ببنية النموذج وتمثيل المتغيرات على الشبكة وبالافتراضات العددية والفيزيائية. ينبغي توثيق الوحدات والإحداثيات والمرجع الزمني ومجال صلاحية كل تقريب قبل تفسير المخرجات."},{"type":"heading","text":"خطوات العمل"},{"type":"list","items":["تحديد المتغيرات والمدخلات والمخرجات ومجالاتها ووحداتها.","فحص جودة الرصد والتحليل الابتدائي والشروط الحدية.","اختيار الإعدادات العددية والفيزيائية المناسبة للمقياس.","تنفيذ اختبار حساسية لتغيير الإعدادات المؤثرة.","مقارنة المخرجات برصد مستقل وتحليل الأخطاء مكانياً وزمنياً."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تجربة تحقق","text":"أنشئ تجربتين تختلفان في إعداد واحد مرتبط بموضوع التحقق من التنبؤ العددي مع تثبيت بقية الشروط. قارن الحقول الناتجة ومقاييس الخطأ، ثم حدد إن كان الفرق ذا دلالة تشغيلية أم يقع ضمن التباين المتوقع."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اقترح لوحة تحقق لحرارة سطحية وهطول، وبيّن لماذا لا يكفي مقياس واحد لتقييم كليهما."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["أخطاء الرصد والتحليل الابتدائي.","عدم كفاية الدقة المكانية أو الزمنية.","تبسيط العمليات الفيزيائية دون الشبكية.","عدم اتساق الوحدات أو أزمنة الصلاحية.","اختيار عينة تحقق غير ممثلة أو غير مستقلة."]},{"type":"callout","text":"مبدأ مهني: لا تقارن نموذجين قبل توحيد الفترة المرجعية والمتغير والوحدة وطريقة المطابقة المكانية والزمنية."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يقدم التحقق من التنبؤ العددي إطاراً لفهم كيفية بناء التنبؤ العددي وتقييمه، ويؤكد أن جودة الناتج تعتمد على تكامل الفيزياء والرياضيات والبيانات والتحقق المستقل."}]}'::jsonb,6150,60,'["شرح المفاهيم الأساسية في التحقق من التنبؤ العددي","تحديد المدخلات والافتراضات العددية والفيزيائية","تصميم اختبار تحقق وتحليل عدم اليقين"]'::jsonb,'الفيزياء والمعالجة والتحقق')
)
insert into public.academy_lessons(course_id,chapter_id,unit_id,chapter_title,unit_title,slug,title,summary,content,published,sort_order,estimated_minutes,learning_objectives,level)
select c.id,ch.id,case when d.unit_title='البنية العددية واستيعاب البيانات' then u1.id else u2.id end,
'النمذجة العددية واستيعاب البيانات الجوية',d.unit_title,d.slug,d.title,d.summary,d.content,false,d.ord,d.mins,d.objectives,'advanced'
from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,level=excluded.level;